(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["zu"] = {"ui":{"skip":"Yeqela ukuya okuqukethwe","back":"← Buyela ku-AI-gile","lang.button":"Ulimi: {name}","lang.dialog":"Khetha ulimi","lang.search":"Sesha izilimi","lang.none":"Alukho ulimi oluhambisanayo","lang.notYet":"{name} alukahunyushwa okwamanje","theme.aria":"Shintsha phakathi kwetimu ekhanyayo nemnyama","theme.toLight":"Shintshela etimini ekhanyayo","theme.toDark":"Shintshela etimini emnyama","words.underline":"Dweba umugqa ngaphansi kwalawa magama ekhasini","words.underlineHelp":"Beka i-mouse phezu kwegama elinamachashazi noma ulithinte ukuze ubone ukuthi lisho ukuthini.","index.title":"AI-gile: iqembu lakho le-AI lokuthuthukisa, ebhodini elilodwa","index.description":"I-AI-gile yibhodi le-kanban lamaqembu e-AI abhala ikhodi. Asebenza ngenkathi ulele; wena uthola inqwaba emfushane yezinto zokuthatha isinqumo, ukuhlola nokwamukela.","hero.logoAlt":"Isithonjana sebhodi le-AI-gile","hero.h1.html":"Iqembu lakho le-AI lokuthuthukisa, ebhodini&nbsp;elilodwa.","hero.alpha":"🐣 I-pre-alpha evaliwe","hero.alphaTitle":"Kusenesikhathi futhi akukaqedwa: siyabonga ngokuzama!","hero.lede":"Akha ngenkathi ulele. Uvuka kunqwaba emfushane eyodwa: imibuzo embalwa, izinto ezimbalwa zokuhlola, idayimane elilodwa noma amabili ansomi. Chofoza, yamukela, ubuyele ekhofini lakho.","dl.windows":"Uhlelo lwe-Windows","dl.browser":"Lusebenzise kusiphequluli sakho","dl.soon":"Kuyeza maduze","dl.notify":"🔔 Ngazise lapho livulwa","dl.notifySmall":"I-alpha noma i-beta","hero.secondary":"I-agile, kodwa iqembu alidingi ikhofi le-stand-up. (Nokho liyazenza ama-stand-up.)","pitch.h2":"I-AI-gile ngamagama amaningi noma amancane njengoba ufuna","pitch.lede":"Khetha ubude, kusukela egameni elilodwa kuya kwangu-144. Ubude ngabunye buyincazelo yabo, ebhalelwe leso silinganiso. Donsa isilayidi noma sebenzisa imicibisholo.","pitch.rangeLabel":"Ubude ngamagama","pitch.dice":"🎲 enye inguqulo","pitch.words.one":"igama elingu-{n}","pitch.words.other":"amagama angu-{n}","pitch.letters.one":"uhlamvu olungu-{n}","pitch.letters.other":"izinhlamvu ezingu-{n}","pitch.chars.one":"uhlamvu olungu-{n}","pitch.chars.other":"izinhlamvu ezingu-{n}","count.line.html.one":"ikhadi elingu-{n} ebhodini khona manje","count.line.html.other":"amakhadi angu-{n} ebhodini khona manje","features.aria":"Okwenzayo","f.pile.h":"Inqwaba eyodwa yakho","f.pile.html":"<b>Kuwe</b> iqoqe konke okukulindele kuwo wonke amaphrojekthi: imibuzo, izinto zokuhlola, imisebenzi umuntu kuphela ayenzayo. Ulayini wakho ukutshela ukuthi yini elandelayo nokuthi kuthatha isikhathi esingakanani.","f.sleep.h":"Amaqembu asebenza ulele","f.sleep.p":"Iphrojekthi ngayinye inomholi neqembu lama-ejenti e-AI. Phawula ekhadini futhi iqembu liyavuka, lenze umsebenzi, liwubuyisele nezinyathelo umuntu ozikhathele angazilandela.","f.tester.h":"Umhloli we-AI uhlola kuqala","f.tester.p":"Ngaphambi kokuba kukufinyelele, umhloli ulandela izinyathelo kukhophi yohlelo bese ekukhombisa ayekubonile, ngesithombe-skrini. Hlola ngokushesha okwedlulile bese wamukela ngokuchofoza kanye.","f.proof.h":"Ubufakazi, hhayi izithembiso","f.proof.p":"Ukudluliselwa ngakunye kukhombisa okushintshile: amafayela, umahluko, izithombe-skrini. Akudingeki uvule uhlelo ngalunye ukuze ubone ukuthi sekuphelile yini.","f.chat.h":"Xoxa nabaholi bakho","f.chat.p":"Umugqa ofana nowe-Discord: isithonjana esisodwa kuphrojekthi ngayinye, amadayimane ansomi kokudinga wena. Thumela umholi umbono; bayiguqulela emakhadini nasepulanini, nenkinobho ethi ✅ Qala.","f.tidy.h":"Iziqoqa ngokwayo","f.tidy.p":"Amakhadi ahlobene ayahlangana abe linye, izihloko ezididayo ziyalungiswa, futhi ukuhlolwa kwamathokheni kugcina ikhodi incane. Izinto ezimbalwa zokushintsha phakathi kwazo, okuncane ongacabanga ngakho.","f.private.h":"Kungokwakho, ekhompyutheni yakho","f.private.li1":"Ibhodi lisebenza emshinini wakho futhi lilandela wena kuphela.","f.private.li2":"Imilayezo eyimfihlo phakathi kwabantu ibethelwe isuka ekugcineni iye ekugcineni.","f.private.li3":"Awekho ama-akhawunti, awekho ama-tracker, awekho amakhukhi.","f.lang.h":"Ngolimi lwakho","f.lang.p":"Izilimi ezingaphezu kwekhulu namashumi amabili, kusukela esiDashi, isiWelsh nesiJapane kuya umphangi wasolwandle, isiYoda nesiKlingon, nokushintsha ngokushesha kubuyele esiNgisini emagameni abathuthukisi.","tl.aria":"Isikhathi esisukela engxoxweni yokuqala kuya emgwaqweni wesikhathi esizayo","tl.h2":"Kusukela engxoxweni yokuqala kuya kokulandelayo","tl.lede":"Amadethi nezikhathi zangempela, ngesikhathi sendawo yakho. Ngemva kwanamuhla kuyisu, akukho madethi aqinisekisiwe.","tl.today":"Namuhla","tl.planned":"kuhlelwe","tl.cards.one":"ikhadi elingu-{n}","tl.cards.other":"amakhadi angu-{n}","join.h2":"Joyina","join.lede":"I-AI-gile yakhiwa umuntu omncane kanye nenqwaba yama-ejenti anesineke. Okwamanje iyimfihlo, kuyi-alpha evaliwe nabangani. Ungathanda ukuzama lapho ivuleka?","join.btn":"Bhalisa isithakazelo","join.small":"Sizokubhalela nge-imeyili, akukho okunye","footer.tag":"I-AI-gile. Awekho ama-tracker, awekho amakhukhi, awekho ikhofi le-stand-up.","footer.licence":"Ilayisense yebhizinisi","footer.status":"Isimo","footer.privacy":"Esikugcinayo","form.sending":"Iyathumela…","form.failed":"Akusebenzanga: zama futhi emuva kwesikhathi.","form.offline":"Asikwazanga ukufinyelela ku-AI-gile: zama futhi emuva kwesikhathi.","form.keep":"Sikusebenzisela kuphela ukukuphendula, bese sikususa. Awekho ama-tracker, awekho amakhukhi.","form.keepLink":"Esikugcinayo","interest.title":"I-AI-gile: ngazise lapho i-alpha ivulwa","interest.description":"Shiya i-imeyili yakho ukuze uzwe lapho i-alpha noma i-beta evaliwe ye-AI-gile ivulwa.","interest.h1":"🔔 Ngazise lapho livulwa","interest.lede":"I-AI-gile iku-pre-alpha evaliwe. Shiya i-imeyili yakho futhi sizobhala kanye kuphela, lapho kunendawo yakho.","interest.email":"I-imeyili yakho","interest.which":"Ukuhlolwa kuphi?","interest.alpha":"I-alpha evaliwe: ekuqaleni, ayikaphelele, ushintsho oluningi","interest.beta":"I-beta: iqinile kakhulu, kamuva","interest.both":"Noma iyiphi, nanoma iyiphi eza kuqala","interest.submit":"Ngifake ohlwini","interest.thanks":"Siyabonga! Usohlwini.","licence.title":"I-AI-gile: ilayisense yebhizinisi","licence.description":"Usebenzisa i-AI-gile ebhizinisini lakho? Faka isicelo selayisense yebhizinisi mahhala.","licence.h1":"📜 Ilayisense yebhizinisi","licence.lede":"Usebenzisa i-AI-gile emsebenzini? Sitshele ukuthi ungubani nokuthi wenzani. Uma kwenza okuhle, ilayisense ayibizi lutho.","licence.company":"Inkampani","licence.website":"Iwebhusayithi","licence.what":"Okwenzayo","licence.how":"Ikusiza kanjani umhlaba","licence.email":"I-imeyili","licence.submit":"Faka isicelo","licence.thanks":"Siyabonga! Sizophendula nge-imeyili.","status.title":"Isimo se-AI-gile","status.h1":"Isimo se-AI-gile","status.quiet":"Konke kuthule","status.intro":"Ingabe i-AI-gile iyasebenza manje? Leli khasi lihlola iwebhusayithi, ukwabelana ngamabhodi, izingcingo nokulanda njalo ngemizuzu engu-5.","status.up":"Iyasebenza (iphendule ngo-{ms} ms)","status.slow":"Ayiphendulanga ekuhloleni kokugcina, iyazama futhi","status.down":"Ayisebenzi: ayiphendulanga ekuhloleni okubili kokugcina","status.svc.web":"Iwebhusayithi","status.svc.web.offers":"Le sayithi: ukuthi iyini i-AI-gile, nefomu elithi ngazise","status.svc.boards":"Ukwabelana ngamabhodi","status.svc.boards.offers":"Amabhodi omphakathi, imilayezo phakathi kwabangane nezimemo","status.svc.calls":"Izingcingo","status.svc.calls.offers":"Izwi, ividiyo nokwabelana ngesikrini ku-AI-gile","status.svc.download":"Ukulanda","status.svc.download.offers":"Isifaki se-Windows nezixhumanisi zezimemo","status.checking":"Iyahlola…","status.offline":"Asikwazi ukufinyelela insizakalo yesimo okwamanje (iyazama futhi)","status.updated":"ibuyekezwe {ago}","status.justNow":"khona manje","status.min":"imizuzu engu-{n} edlule","status.hours":"amahora angu-{n} edlule","status.days":"izinsuku ezingu-{n} edlule","privacy.title":"I-AI-gile: esikugcinayo","privacy.h1":"Esikugcinayo","privacy.lede":"Ngamafuphi: kuphela lokho osithumelela kona, futhi hhayi isikhathi eside.","privacy.only":"Kuphela lokho osithumelela kona: lokho okubhala efomini, njenge-imeyili yakho. Akukho okunye ngawe.","privacy.sealed":"Kuvalwa ngophawu ukuze iseva yethu ingakwazi ukukufunda: kusesiphequluli sakho ngaphambi kokuthi kuhambe (esipheqululini esidala, ngokushesha nje uma kufika). Yibhodi lethu kuphela elingakuvula.","privacy.server":"Kususwa kuseva ngokushesha nje uma kufika ebhodini lethu. Noma yini esekhona ngemva kwezinsuku ezingu-30 iyasuswa noma kunjalo.","privacy.board":"Sikugcina ebhodini lethu kuze kube yilapho sesikuphendulile, bese sikususa nalapho.","privacy.none":"Awekho ama-tracker, awekho amakhukhi, akukho ukuhlaziywa.","privacy.local":"Ulimi lwakho nokukhetha kwakho ukukhanya noma ubumnyama kuhlala esipheqululini sakho. Akukaze kuthunyelwe kithi.","privacy.ask":"Ufuna kususwe ngokushesha? Phendula i-imeyili yethu usitshele.","live.h2":"Bukela ngenkathi yakhiwa, bukhoma","live.caption":"Wonke ikhadi lifihliwe: ubona isimo somsebenzi, hhayi amagama.","live.watching.one":"bukhoma: {n} uyabuka","live.watching.other":"bukhoma: {n} bayabuka","live.last.now":"Ikhadi lokugcina lihanjiswe nje manje","live.last.min.one":"Ikhadi lokugcina lihanjiswe umzuzu ongu-{n} owedlule","live.last.min.other":"Ikhadi lokugcina lihanjiswe imizuzu engu-{n} edlule","live.last.hour.one":"Ikhadi lokugcina lihanjiswe ihora elingu-{n} eledlule","live.last.hour.other":"Ikhadi lokugcina lihanjiswe amahora angu-{n} edlule","live.last.day.one":"Ikhadi lokugcina lihanjiswe usuku olungu-{n} olwedlule","live.last.day.other":"Ikhadi lokugcina lihanjiswe izinsuku ezingu-{n} ezedlule","live.offline":"Ibhodi elibukhoma lithatha ikhefu elifushane. Buya maduze.","live.cols":"Backlog|Okufanele kwenziwe|Kuyaqhubeka|Iqembu liyahlola|Kuwe ukuthi test|Kweqembu|Kuphelile"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Amarobhothi.","Nikeza."]},{"n":2,"texts":["Kanban yamarobhothi.","Ama-ejenti, ahlelekile.","Imibono, yakhiwe."]},{"n":3,"texts":["Ibhodi lamarobhothi lamahhala.","Imibono iba izici.","Kanban yama-ejenti, mahhala."]},{"n":5,"texts":["Ibhodi eliqhutshwa ngama-ejenti, lamahhala nje.","Wena ubhala amakhadi. Ama-ejenti akha.","Mahhala, ekhaya, ihloliwe, nenhlanhla encane."]},{"n":8,"texts":["Ibhodi le-kanban lamahhala lapho ama-ejenti e-AI asebenza khona.","Bhala umbono. Ama-ejenti awakhe. Wena uyawamukela.","I-agile yomuntu oyedwa namarobhothi amaningi anesineke nje."]},{"n":13,"texts":["Ibhodi le-kanban ekhompyutheni yakho lapho ama-ejenti e-AI athatha khona amakhadi.","Bhala umbono wakho. Iqembu lama-ejenti liyawakha lapho. Bese umhloli we-AI uyawuhlola ngemva kwalokho.","Mahhala, awekho ama-akhawunti, awekho ama-tracker: ibhodi, amarobhothi athile, wena nguwe oyinhloko."]},{"n":21,"texts":["I-AI-gile yibhodi le-kanban lokusebenza nama-ejenti e-AI abhala ikhodi. Wona athatha amakhadi bese wena uwahlola futhi uwamukele ngokwakho lapho eseqedile.","Iphrojekthi ngayinye ithola umholi kanye neqembu lama-ejenti e-AI. Phawula noma yiliphi ikhadi, bese iqembu liyavuka liqale ukusebenza ngokushesha okukhulu.","Yibhodi lemisebenzi yomuntu siqu, lamahhala, elisebenza ekhompyutheni yakho uqobo. Abasebenzi bangamarobhothi nje. Futhi ophendula ngokuthi yebo nguwe wedwa."]},{"n":34,"texts":["Ubeka imibono yakho ebhodini. Iqembu lama-ejenti e-AI liyiguqula ibe yizici ezisebenzayo, liyazihlola, bese liziletha kuwe nezinyathelo zokuzama. Akukho okubalwa njengokuphelile ngaphandle kokuthi wena uthi kunjalo. Konke kwenzeka ekhompyutheni yakho.","I-AI-gile yibhodi le-kanban elenziwe ekhaya, elakhiwa nguRich ngosizo olukhulu lwama-ejenti manje alawulwa yilo. Lamahhala, lisebenza ekhompyutheni yakho, futhi labelwana nabangani, alithengiswa muntu. Lakhelwe ukusiza nokujabulisa, akukho okunye okufihliwe nhlobo.","Cabanga ibhodi le-kanban elijwayelekile, namakholomu asuka ku-Backlog aze afike ku-Done, kodwa amakhadi athathwa ama-ejenti e-AI. Abika inqubekela phambili, abuza lapho ebambekile, futhi njalo alinde ukuvuma kwakho, uthi yebo noma cha."]},{"n":55,"texts":["I-AI-gile yibhodi le-kanban lapho iqembu lakhiwe ngama-ejenti e-AI. Iphrojekthi ngayinye inomholi ohlela umsebenzi, nabasizi abawakhayo. Uma isici sesilungile, umhloli we-AI uyasizama, athathe nesithombe-skrini, bese sifika enqwabeni yakho. Ungasamukela, noma uphawule bese iqembu liqala kabusha ukusebenza ngokukhulu ukunaka. Konke kulula futhi kucacile, ngakho ungabuyela ekhofini lakho.","Laqala njengendlela yomuntu oyedwa yokulandelela izikhathi eziningi zokubhala ikhodi nge-AI ngasikhathi sinye, laze lakhula laba yibhodi langempela. Lisebenza emshinini wakho, alidingi i-akhawunti, futhi alinawo ama-tracker. Lamahhala kubangani nakuwo wonke onelukuluku. Alikaphelele, ngakho lindela ubukhali obuthile nezimanga ezimbalwa ngezikhathi ezithile. Kungcono ukuqala kancane, kanjalo siyakhula ndawonye nabangani.","Nanku iqiniso eliqinile. Kusadingeka ube nemibono yakho, futhi kusadingeka uhlole imiphumela ngokwakho. I-AI-gile yenza konke okuphakathi: igcina amakhadi ehleleke kahle, ivusa i-ejenti efanele uma uphawula, ikhombisa ncamashi okushintshile, futhi ikubeka konke enqwabeni eyodwa emfushane eyakho kuphela. Ukucabanga nokukhetha kusalokhu kungokwakho, futhi lokho kunjalo ngenhloso."]},{"n":89,"texts":["I-AI-gile yibhodi le-kanban lamahhala olisebenzisa ekhompyutheni yakho uqobo. Esikhundleni sabantu, iphrojekthi ngayinye inalo iqembu lama-ejenti e-AI: umholi oguqula imibono yakho ibe amakhadi nepulani, nabasizi abathatha amakhadi ngokulandelana kokubaluleka. Uma okuthile sekwakhiwe, umhloli we-AI ulandela izinyathelo zokuhlola bese ekukhombisa lokho akubonile ngesithombe-skrini. Bese kulinda enqwabeni eyodwa ethi Kuwe. Uyakwamukela, noma uphawule bese iqembu lizama futhi kusukela ekuqaleni. Akukho nakanye okufika ku-Done ngaphandle kwakho wena. Wonke umsebenzi wenzeka ekhompyutheni yakho, futhi awudingi i-akhawunti ukuze uwusebenzise.","Ezinye izici ongase ungazilindele. Umqaphi wasebusuku ugcina ikholomu ethi To do igcwele ngenkathi ulele, ekhetha amakhadi angadingi mpendulo evela kuwe. Isibali samathokheni sikhombisa ukuthi ama-ejenti asebenzise malini namuhla nalesi sonto, futhi imodi ethi No Token Mode iwatshela ukuba ayeke ukusebenzisa. Ungathumela imilayezo kubangani, futhi imilayezo eyimfihlo ibethelwe ngokuphelele. Ibhodi likhuluma izilimi ezingaba ngu-120, kubandakanya isiDashi, isiFlemish, umphangi wasolwandle nesiKlingon. Akukho kulokhu okubiza lutho, futhi akekho ozama ukukudayisela lona. Konke lokhu kwenzelwe ukuba ulale kahle, wazi ukuthi umsebenzi uqhubeka.","I-AI-gile iyiphrojekthi encane, yomuntu siqu, hhayi inkampani. URich wayefuna ukunakekela amaphrojekthi amaningi e-AI ngaphandle kokuvula uhlelo ngalunye ukuze alihlole, ngakho yena nama-ejenti akha ibhodi, base besebenzisa lona ibhodi ukwakha okusele kwalo uqobo. Iku-pre-alpha evaliwe, okusho ukuthi isebenza, ikakhulukazi, kwabangani abambalwa kuphela. Alikho ikhasi lamanani, alikho ileta yezindaba, futhi alikho icebo lokukhula. Uma lizwakala linomsebenzi kuwe, ungacela ukulizama lapho livuleka kancane nje. Uma ufuna ukuzama, bhala nje ukucela, bese sikuphendula ngokushesha uma sesikulungele kahle."]},{"n":144,"texts":["I-AI-gile yibhodi le-kanban lomuntu oyedwa nama-ejenti amaningi e-AI. Lisebenza ekhompyutheni yakho uqobo futhi lamahhala ngokuphelele. Wengeza amaphrojekthi, futhi iphrojekthi ngayinye ithola umholi neqembu elincane. Uxoxa nomholi, kufana kakhulu ne-Discord, uchaze umbono wakho; umholi uwuguqulela emakhadini nasepulanini, bese elinda ukuthi ucindezele u-Qala. Iqembu lisebenza ngamakhadi ngokulandelana kokubaluleka, lisebenzisa umugqa wemiyalo olula owenzelwe amamodeli olimi. Ngaphambi kokuba kukubuyele, umhloli we-AI ulandela izinyathelo kukhophi yohlelo bese enamathisela isithombe-skrini. Umsebenzi oqediwe uwela enqwabeni yakho kanye namafayela ashintshile nomahluko wawo. Uyawamukela, noma ushiye isikhumbuzo bese iqembu livuka lizame futhi. Wena kuphela ongashintshela ikhadi ku-Done, akekho omunye. Konke okwenziwayo kuyabonakala, ngakho awudingi ukuthemba ngokungaboni. Ibhodi lilula, linesineke, futhi lihlala lilinde izinqumo zakho ngokuthula okukhulu. Kuphelele kumuntu ofuna ukunyakazisa umsebenzi ngaphandle kokuhlala kuwo usuku lonke.","Usuku ne-AI-gile, kafushane. Kusihlwa uphawula amazwana ambalwa: le nkinobho isendaweni engafanele, lolo hlu kufanele luhlelwe, ingabe singaba nemodi emnyama yini. Uyalala. Ama-ejenti afunda amazwana, enze izinguquko, azihlole, bese ezibuyisela kuwe. Uma ikholomu ethi To do iphela, umqaphi wasebusuku uyigcwalisa evela ku-backlog ngamakhadi angadingi mpendulo evela kuwe. Ekuseni kunenqwaba eyodwa emfushane: imibuzo embalwa nezinto ezimbalwa zokuzama, ngayinye inezinyathelo umuntu onokulala angazilandela kanye nesithombe-skrini sokuthi isebenza. Uchofoza ngazo ngayinye, wamukele ezinhle bese uthumela ezisele emuva ukuze zilungiswe. Isibali samathokheni sikhombisa ukuthi konke kusebenzise malini, futhi imodi ethi No Token Mode ikhona ezinsukwini zokonga. Bese udla ibhulakufesi, okungakasizi ngakho ama-ejenti. Ngesonto elilandelayo ungenza okufanayo, uphinde ubone ukuthi kuthatha isikhathi esingakanani. Awudingi ukuhlala usuku lonke ubheke isikrini, futhi ibhodi lihlala lilungele wena.","Okokuqala, ukuthi i-AI-gile ayiyona yini. Akuyona inkampani entsha, akuthengiswa, futhi akekho oqoqa idatha yakho. Yibhodi lamahhala elisebenza ekhompyutheni yakho, ngaphandle kwama-akhawunti, ngaphandle kwama-tracker nangaphandle kwamakhukhi. Yini yona: indawo eyodwa ehlelekile yokubona wonke amaphrojekthi e-AI ngasikhathi sinye, neqembu lama-ejenti enza amakhadi nawe uthatha izinqumo. Ihlanganisa amakhadi ahlobene, ilungisa izihloko ezididayo, futhi ibheka ukuthi ikhodi ihlala incane kangakanani. Ikhuluma izilimi ezingaba ngu-120, kusukela esiDashi nesiFlemish kuya kumphangi wasolwandle nesiKlingon. Abangani bangathumelana imilayezo, ngasese futhi ibethelwe. Yakhiwe nguRich nenqwaba yama-ejenti anesineke, ikakhulukazi isebenzisa yona ngokwayo. Iku-pre-alpha evaliwe, ngakho inobukhali kwezinye izindawo. Uma kuzwakala kumnandi, cela kahle futhi ungangena kusenesikhathi. Kuyibhodi elincane elinenhliziyo, elenzelwe ukuba lisize abantu abangenaso isikhathi sokuhlola konke ngabo ngokwabo. Futhi kungumsebenzi oqhubekayo, kusakhula nsuku zonke."]}],"quips":{"1":"Igama elilodwa. Lilukhuni. Mhlawumbe lilukhuni kakhulu.","3":"Amagama amathathu. Seliqinisile kunamakhasi amaningi emikhiqizo.","8":"Amagama ayisishiyagalombili. Kusamfushane kuno-stand-up.","21":"Ubude bungamaphoyinti ezindaba, ngendlela. Yebo, kunjalo.","55":"Amagama angamashumi amahlanu nanhlanu. Amakhadi amabili aphelile ngenkathi ufunda lokho.","144":"Lena yinde. Alikho elingu-233. Ama-ejenti aye ukulala."}},"timeline":{"first-idea.name":"Umbono wokuqala","first-idea.line":"Ingxoxo yokuqala nya, ngaphambi kokuba kube khona ikhodi.","first-board.name":"Ibhodi lokuqala","first-board.line":"Ibhodi elilandelela ukwakhiwa kwalo: amakhadi, amakholomu, donsa uphonse, amaphrojekthi.","team-roles.name":"Iqembu nezindima","team-roles.line":"Amaphrofayela ama-ejenti, amathempulethi eqembu, izikhala nokuthi ngubani owenzani.","install.name":"Ukufaka nokukhishwa","install.line":"I-zip umngani angayifaka, ukuzibuyekeza, amashaneli nokubuyela emuva.","usage-saver.name":"Ukonga ukusetshenziswa","usage-saver.line":"Linganisa izindleko zokusebenza, gcina ikhodi incane, onge umkhawulo wakho.","friends.name":"Abangani nokwabelana","friends.line":"Imilayezo eyimfihlo, isidlulisi esixubekile, izimemo, izindima namaphrojekthi abelwanayo.","languages.name":"Izilimi","languages.line":"Yonke imibhalo yesikrini ifayelini lolimi, kuqala ngesiDashi nesiFlemish.","ai-tester.name":"Umhloli we-AI","ai-tester.line":"Umhloli uhlola ukudluliselwa ngakunye kuqala bese ekhombisa ayekubonile.","website.name":"Iwebhusayithi","website.line":"I-aigile.lol, i-teaser nalesi sikhathi.","streaming.name":"Ingxoxo nokusakaza","streaming.line":"I-Discord, i-Twitch, i-OBS, imodi yomsakazi, ama-GIF nama-emoji.","no-ai.name":"Uhlelo olungenayo i-AI","no-ai.line":"Ibhodi labantu abakhipha ikhodi ngaphandle kwe-AI, namabhodi omphakathi.","night-watch.name":"Ukuqapha ebusuku","night-watch.line":"Umqaphi ne-Scrum Master baqhubekisa amaqembu emsebenzini ngenkathi ulele.","p-more.name":"Konke okunye","p-more.line":"Imibono emincane ekhona isalindele ithuba layo.","p-android.name":"Ifoni ne-Android","p-android.line":"Finyelela ibhodi lakho ofonini, bese kuba uhlelo lwangempela lwe-Android.","p-release.name":"I-alpha nangale kwayo","p-release.line":"I-alpha evaliwe, isayithi eliphilayo, bese i-beta.","p-languages.name":"Izilimi eziningi","p-languages.line":"Izilimi ezingaphezu kwekhulu, nemodi yokucwiliswa yabafundi.","p-engines.name":"Izinjini ze-AI eziningi","p-engines.line":"Khetha i-Claude, i-Codex noma i-Gemini ku-ejenti ngayinye.","p-pro.name":"Umkhuba wochwepheshe","p-pro.line":"Amalebula obungozi, amasango okuhlanganisa, amakhadi ezehlakalo nezivikelo.","p-self.name":"Ukukunakekela","p-self.line":"Imodi yokukhathala, izikhumbuzi zokuzinakekela ne-4:20.","p-servers.name":"Amaseva nobukhulu","p-servers.line":"Izilungiselelo zamaseva jikelele, izindima nokuhlela ukukhula.","p-livestream.name":"Okungeziwe kokusakaza","p-livestream.line":"Ingxoxo ye-Twitch, ama-emoji ngokwezifiso nombono womphakathi ophilayo."},"words":{"button":"📖 Amagama abathuthukisi","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Sesha igama…","none":"Alikho igama elifana nalelo.","close":"Vala","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"I-folda yekhodi yephrojekthi nomlando wayo ophelele wama-commit, kaningi igcinwa ku-GitHub futhi.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Umugqa ohlukile womsebenzi ekhodini, ukuze izinguquko zenziwe ngaphandle kokuthinta inguqulo eyinhloko.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Isithombe esigciniwe sekhodi, esinenothi elifushane lokushintshile. Ungabuyela kunye noma nini.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Ukuthumela izithombe ezigciniwe (ama-commit) ukusuka kule khompyutha uye ku-GitHub, ukuze kugcinwe isipele futhi kwabelwane."},{"id":"merge","g":"build","word":"Merge","text":"Ukuhlanganisa izinguquko ze-branch emuva enguqulweni eyinhloko."},{"id":"pr","g":"build","word":"Pull request","text":"Ukucela ukuthi izinguquko ze-branch zihlolwe futhi zihlanganiswe enguqulweni eyinhloko.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Ukuhlela ikhodi ngaphandle kokushintsha okwenzayo: amafayela amancane, amagama acacile, ukuphindaphinda okuncane."},{"id":"bug","g":"build","word":"Bug","text":"Into engasebenzi ngendlela okufanele isebenze ngayo.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"Ukuzama ucezu lomsebenzi oqediwe ukubona ukuthi wenza okucelwe, ngaphambi kokuwamukela.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Ukubeka inguqulo entsha ukuthi iphile, isibonelo kuseva lapho abantu bayisebenzisa khona."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Imibono nomsebenzi ongakahlelwa. Akukho okusetshenzwa kukho kuze kuhambe kuya ku-Okufanele kwenziwe."},{"id":"sprint","g":"team","word":"Sprint","text":"Isikhathi esifushane somsebenzi (kaningi isonto noma amabili) onamakhadi avunyelwene okufanele aqedwe.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Ukubheka okusheshayo: ilungu ngalinye leqembu lenzeni, lenzani ngokulandelayo, nokuthi yini ebamisayo.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Ibhodi elinezingqimba (Okufanele kwenziwe, Kuyaqhubeka, Kuphelile) lapho amakhadi ahamba esuka kwesobunxele aye kwesokudla njengoba umsebenzi wenzeka."},{"id":"wip","g":"team","word":"Umkhawulo we-WIP","text":"Umsebenzi oqhubekayo: amakhadi amaningi isingqimba okufanele sibambe, ukuze iqembu liqede izinto ngaphambi kokuqala ezengeziwe.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"I-AI esebenza yodwa emsebenzini: ifunda ikhodi, yenze izinguquko, iqhube ukuhlola, ibike emuva.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"Iyunithi lapho ukusetshenziswa kwe-AI kubalwa khona: cishe izinhlamvu ezimbalwa zombhalo ezifundwayo noma ezibhaliwe. Ama-token ambalwa, uhlelo olusele lukhulu.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Umyalo omncane osebenza wodwa ngesikhathi esimisiwe, isb. lapho iseshini ye-AI iqala, ukuze iqembu lizwe amakhomenti akho.","also":["hooks"]}]}};
